package net.zartra.gui;
import org.bukkit.entity.Player;import java.util.*;
final class ChatInputManager { interface Callback { void run(Player player,String text); } private final Map<UUID,Entry> map=Collections.synchronizedMap(new HashMap<UUID,Entry>());private final long ttl; ChatInputManager(long seconds){ttl=Math.max(10,seconds)*1000L;} void begin(Player p,Callback cb){map.put(p.getUniqueId(),new Entry(System.currentTimeMillis(),cb));p.sendMessage(Chat.c("&eType a value in chat, or &ccancel&e."));} Entry take(Player p){Entry x=map.remove(p.getUniqueId());return x!=null&&System.currentTimeMillis()-x.time<=ttl?x:null;}void remove(Player p){map.remove(p.getUniqueId());}void clear(){map.clear();}static final class Entry{final long time;final Callback cb;Entry(long t,Callback c){time=t;cb=c;}} }
